/* @lc app=leetcode id=2581 lang=kotlin */ class Solution { fun rootCount(edges: Array<IntArray>, guesses: Array<IntArray>, k: Int): Int = edges.size.plus(1).let { n -> Array(n) { mutableListOf<Int>() }.apply { edges.forEach { e -> get(e[0]).add(e[1]).also { get(e[1]).add(e[0]) } } }.let { adj -> guesses.map { it[0] to it[1] }.toSet().let { gSet -> DeepRecursiveFunction<Pair<Int, Int>, Int> { (u, p) -> adj[u].sumOf { v -> if (v == p) 0 else (if (gSet.contains(u to v)) 1 else 0) + callRecursive(v to u) } }.let { dfs1 -> dfs1(0 to -1).let { initial -> DeepRecursiveFunction<Triple<Int, Int, Int>, Int> { (u, p, s) -> (if (s >= k) 1 else 0) + adj[u].sumOf { v -> if (v == p) 0 else callRecursive(Triple(v, u, s - (if (gSet.contains(u to v)) 1 else 0) + (if (gSet.contains(v to u)) 1 else 0))) } }(Triple(0, -1, initial)) } } } } } }